 private void refresh(){if(prefs==null)return;boolean on=prefs.getBoolean("bot_enabled",false),bi=isBusinessInstalled(),ac=WhatsAppAccessibilityService.isEnabled(this),no=isNotificationAccessEnabled();set(wa,bi?"ATIVO":"OFF",bi);set(acc,ac?"ATIVA":"OFF",ac);set(notif,no?"ATIVAS":"OFF",no);set(engine,on?"ATIVO":"PAUSADO",on);if(mode!=null){mode.setText(on?"MODO ATUAL:  AUTOMÁTICO":"MODO ATUAL:  PAUSADO");mode.setTextColor(on?GREEN:RED);}if(power!=null){power.active=on;power.invalidate();}if(online!=null){online.setText(on?"● ONLINE":"● PAUSADO");online.setTextColor(on?GREEN:RED);}setValue(lastChat,prefs.getString("accessibility_last_conversation",""));setValue(lastMsg,prefs.getString("accessibility_last_message",""));setValue(lastReply,prefs.getString("accessibility_last_reply",""));setValue(lastStatus,prefs.getString("accessibility_last_status",""));int p=prefs.getInt("neon_pending_replies",0),s=prefs.getInt("stats_sent_today",0),f=prefs.getInt("stats_failed_today",0),a=prefs.getInt("stats_attempts_today",0),t=prefs.getInt("stats_chats_today",0);if(pending!=null)pending.setText("• Pendentes     "+p);if(sent!=null)sent.setText("• Enviadas       "+s);if(fail!=null)fail.setText("• Falhas            "+f);if(attempts!=null)attempts.setText("• Tentativas     "+a);if(today!=null)today.setText("• Atendimentos     "+t);if(totalSent!=null)totalSent.setText("• Respostas enviadas  "+s);String rr=(s+f)==0?"--":Math.round(100f*s/(s+f))+"%";if(rate!=null)rate.setText("• Taxa de sucesso   "+rr);if(totalFail!=null)totalFail.setText("• Falhas                 "+f);if(successRing!=null){successRing.mark=rr;successRing.invalidate();}}
 private class PowerView extends View{Paint p=new Paint(1);boolean active=true;PowerView(){super(NeonDashboardActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.42f;int co=active?GREEN:RED;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(Color.rgb(15,75,60));c.drawCircle(x,y,r+dp(6),p);p.setStrokeWidth(dp(3));p.setColor(co);p.setShadowLayer(dp(10),0,0,co);c.drawArc(new RectF(x-r,y-r,x+r,y+r),-78,305,false,p);p.setShadowLayer(0,0,0,0);p.setStrokeWidth(dp(5));float ir=r*.43f;c.drawArc(new RectF(x-ir,y-ir,x+ir,y+ir),-45,270,false,p);c.drawLine(x,y-ir*1.35f,x,y+ir*.08f,p);}}
 private class RobotView extends View{Paint p=new Paint(1);RobotView(){super(NeonDashboardActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(PURPLE);p.setShadowLayer(dp(7),0,0,PURPLE);RectF r=new RectF(w*.16f,h*.18f,w*.84f,h*.72f);c.drawRoundRect(r,dp(12),dp(12),p);p.setColor(GREEN);c.drawCircle(w*.38f,h*.43f,dp(3),p);c.drawCircle(w*.62f,h*.43f,dp(3),p);c.drawLine(w*.38f,h*.59f,w*.62f,h*.59f,p);p.setColor(CYAN);c.drawLine(w*.16f,h*.37f,w*.08f,h*.37f,p);c.drawLine(w*.84f,h*.37f,w*.92f,h*.37f,p);p.setColor(PURPLE);c.drawLine(w*.5f,h*.18f,w*.5f,h*.09f,p);c.drawCircle(w*.5f,h*.07f,dp(2),p);}}
 private class ServiceIconView extends View{Paint p=new Paint(1);int kind,color;ServiceIconView(int k,int c){super(NeonDashboardActivity.this);kind=k;color=c;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),x=w/2,y=h/2;p.setColor(color);p.setStrokeWidth(dp(2));p.setStyle(Paint.Style.STROKE);p.setShadowLayer(dp(7),0,0,color);if(kind==0){c.drawCircle(x,y,dp(14),p);Path q=new Path();q.moveTo(x-dp(10),y+dp(10));q.lineTo(x-dp(14),y+dp(15));q.lineTo(x-dp(5),y+dp(12));c.drawPath(q,p);c.drawArc(new RectF(x-dp(7),y-dp(8),x+dp(8),y+dp(8)),-55,115,false,p);}else if(kind==1){c.drawCircle(x,y-dp(10),dp(4),p);c.drawLine(x,y-dp(5),x,y+dp(8),p);c.drawLine(x-dp(10),y,x+dp(10),y,p);c.drawLine(x,y+dp(7),x-dp(8),y+dp(16),p);c.drawLine(x,y+dp(7),x+dp(8),y+dp(16),p);}else if(kind==2){Path b=new Path();b.moveTo(x-dp(11),y+dp(8));b.quadTo(x-dp(9),y+dp(3),x-dp(9),y-dp(4));b.quadTo(x-dp(9),y-dp(13),x,y-dp(13));b.quadTo(x+dp(9),y-dp(13),x+dp(9),y-dp(4));b.quadTo(x+dp(9),y+dp(3),x+dp(11),y+dp(8));b.close();c.drawPath(b,p);c.drawCircle(x,y+dp(12),dp(2),p);}else{RectF r=new RectF(x-dp(13),y-dp(12),x+dp(13),y+dp(12));c.drawRoundRect(r,dp(5),dp(5),p);c.drawCircle(x-dp(5),y-dp(2),dp(2),p);c.drawCircle(x+dp(5),y-dp(2),dp(2),p);c.drawLine(x-dp(6),y+dp(5),x+dp(6),y+dp(5),p);for(int i=-1;i<=1;i+=2){c.drawLine(x+i*dp(17),y-dp(6),x+i*dp(13),y-dp(6),p);c.drawLine(x+i*dp(17),y+dp(6),x+i*dp(13),y+dp(6),p);}}}}
 private class ShieldView extends View{Paint p=new Paint(1);ShieldView(){super(NeonDashboardActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(CYAN);p.setShadowLayer(dp(9),0,0,CYAN);Path path=new Path();path.moveTo(w*.5f,h*.08f);path.lineTo(w*.82f,h*.22f);path.lineTo(w*.75f,h*.67f);path.lineTo(w*.5f,h*.9f);path.lineTo(w*.25f,h*.67f);path.lineTo(w*.18f,h*.22f);path.close();c.drawPath(path,p);p.setColor(GREEN);c.drawRoundRect(new RectF(w*.39f,h*.45f,w*.61f,h*.64f),dp(2),dp(2),p);c.drawArc(new RectF(w*.42f,h*.32f,w*.58f,h*.52f),180,-180,false,p);}}
