 private class SparkView extends View{Paint p=new Paint(1);int color;SparkView(int c){super(NeonDashboardActivity.this);color=c;}protected void onDraw(Canvas c){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(color);Path q=new Path();q.moveTo(0,getHeight()*.65f);q.lineTo(getWidth()*.18f,getHeight()*.48f);q.lineTo(getWidth()*.34f,getHeight()*.62f);q.lineTo(getWidth()*.52f,getHeight()*.28f);q.lineTo(getWidth()*.72f,getHeight()*.55f);q.lineTo(getWidth(),getHeight()*.32f);c.drawPath(q,p);}}
