 private TextView service(LinearLayout p,int kind,String label,int accent){LinearLayout c=col();c.setGravity(Gravity.CENTER);c.setPadding(dp(2),dp(7),dp(2),dp(7));c.setBackground(bg(CARD,BORDER,7,1));ServiceIconView icon=new ServiceIconView(kind,accent);c.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView l=text(label,9,Color.WHITE,true);l.setGravity(Gravity.CENTER);c.addView(l);TextView state=text("...",9,GREEN,true);state.setGravity(Gravity.CENTER);c.addView(state);p.addView(c,new LinearLayout.LayoutParams(0,dp(112),1f));p.addView(spaceH(8));return state;}
 private TextView activityRow(LinearLayout p,int kind,String label){LinearLayout r=row();ServiceIconView icon=new ServiceIconView(kind==3?2:kind,CYAN);r.addView(icon,new LinearLayout.LayoutParams(dp(22),dp(22)));r.addView(text(label,9,MUTED,false),new LinearLayout.LayoutParams(dp(112),-2));TextView v=text("—",9,Color.WHITE,true);r.addView(v,new LinearLayout.LayoutParams(0,-2,1f));p.addView(r);p.addView(space(4));return v;} private TextView metric(LinearLayout p,String s){TextView t=text("• "+s,9,Color.WHITE,false);t.setPadding(0,dp(5),0,0);p.addView(t);return t;} private Button action(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(9);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT_BOLD);b.setAllCaps(false);b.setBackground(bg(Color.rgb(4,14,11),c,6,1));return b;} private Button nav(String s,int c,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextSize(9);b.setTextColor(c);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(l);return b;} private LinearLayout card(int stroke){LinearLayout l=col();l.setPadding(dp(10),dp(9),dp(10),dp(9));l.setBackground(bg(CARD,stroke,7,1));return l;} private void title(LinearLayout r,String s){r.addView(space(13));r.addView(text(s,10,Color.WHITE,true));r.addView(space(6));} private void setValue(TextView v,String s){if(v!=null)v.setText(value(s));} private void set(TextView v,String s,boolean ok){if(v!=null){v.setText(s);v.setTextColor(ok?GREEN:RED);}} private boolean isBusinessInstalled(){try{getPackageManager().getPackageInfo("com.whatsapp.w4b",0);return true;}catch(Throwable t){return false;}} private boolean isNotificationAccessEnabled(){try{String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}catch(Throwable t){return false;}} private GradientDrawable bg(int fill,int stroke,int radius,int width){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(width),stroke);return d;} private GradientDrawable circle(int fill,int stroke,int width){GradientDrawable d=bg(fill,stroke,100,width);d.setShape(GradientDrawable.OVAL);return d;} private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;} private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);return t;} private Space space(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(x)));return s;} private Space spaceH(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(dp(x),1));return s;} private LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,dp(62),1f);} private String value(String s){if(s==null||s.trim().isEmpty())return"—";s=s.trim();return s.length()>52?s.substring(0,49)+"...":s;} private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
